head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gNewWidthSize = 0;
scwin.isCtrl = false;
// grid resize 시작부

frame.SetEvent("onwinstat", OnWinStat);
scwin.gOldWidthSize = frame.width;

///////// 2. 초기화 영역 /////////
/**
