};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_main_OnSelChanged
 * @description tab main On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tab_main_OnSelChanged = async function(nIndex) {
    try {
        if ($c.frame.path("NoData") !== null) {
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF90220.tab_main_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_acode1_OnLoadCompleted
 * @description dts_acode1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_acode1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.panelMsg(panel_msg1, "총 : " + $c.stf.FormatNumberEx(rowcount) + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90220.dts_acode1_OnLoadCompleted" });
    }
};

/**
 * @method
