/**
 * @method
 * @name grd_main1_oncopy
 * @description grd_main1 oncopy 이벤트
 * @param {*} lStarRow lStarRow
 * @param {String} bstrStartColId bstrStartColId
 * @param {*} lEndRow lEndRow
 * @param {String} bstrEndColId bstrEndColId
 * @returns {void}
 * @hidden N
 */
scwin.grd_main1_oncopy = function(lStarRow, bstrStartColId, lEndRow, bstrEndColId) {
    try {
        scwin.CopyToClipboard(StartRow, startColid, EndRow, EndColid, grd_main1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90220.grd_main1_oncopy" });
    }
};

/**
 * @method
 * @name grd_main1_onkeyup
 * @description grd_main1 키 입력 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.grd_main1_onkeyup = function(row, colid, data) {
    try {
        if (scwin.isCtrl === true && data === 83) {
            scwin.save1();
            return false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90220.grd_main1_onkeyup" });
    }
};

/**
 * @method
 * @name grd_main1_OnKeyPress
 * @description grd main1 On Key Press 처리
 * @param {*} keycode keycode
 * @returns {void}
 * @hidden N
 */
scwin.grd_main1_OnKeyPress = function(keycode) {
    try {
        if (keycode === 17) {
            scwin.isCtrl = true;
        } else {
            scwin.isCtrl = false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90220.grd_main1_OnKeyPress" });
    }
};

/**
 * @method
 * @name btn_exec1_onclick
 * @description 「처리」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_exec1_onclick = async function() {
    try {
        let vFORM_CD = txb_form_cd1.getValue();
        let vFORM_VER = txb_form_ver1.getValue();
        if (cmb_exec_type1.getSelectedIndex() < 0) {
            alert("실행할 배치작업을 선택하세요");
            txb_form_cd1.focus();
            return;
        }
        if (vFORM_CD === "") {
            alert("서식코드를 입력하세요.");
            txb_form_cd1.focus();
            return;
        }
        if (cmb_exec_type1.getSelectedIndex() === 0) {
            await scwin.setStckSize1(vFORM_CD, vFORM_VER);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF90220.btn_exec1_onclick" });
    }
};

