///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search1
 * @description search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search1 = async function() {
    let vFORM_CD = txb_form_cd1.getValue();
    let vFORM_VER = txb_form_ver1.getValue();
    let vFILTER = txb_filter1.getValue();
    if (vFORM_CD === "") {
        alert("서식코드를 입력하세요.");
        txb_form_cd1.focus();
        return;
    }
    if (vFORM_VER === "") {
        alert("서식버전을 입력하세요.");
        txb_form_ver1.focus();
        return;
    }
    url += "&FORM_CD=" + vFORM_CD;
    url += "&FORM_VER=" + vFORM_VER;
    url += "&FILTER=" + vFILTER;
    $c.stf.panelMsg(panel_msg1, "로딩중...기다려주세요.");
    const sbmOptions = {
        id : "sbm_dts_acode1",
        action : "/NewDisclosureStatistics.do",
        ref : "",
        target : "dts_acode1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setStckSize1
 * @description set Stck Size1 처리
 * @param {String} pFORM_CD pFORM_CD
 * @param {*} pFORM_VER pFORM_VER
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setStckSize1 = async function(pFORM_CD, pFORM_VER) {
    let res = window.confirm("다소 시간이 소요될 수 있습니다, 실행하겠습니까?");
    if (res) {
        $c.stf.panelMsg(panel_msg1, "처리중...기다려주세요.");
        url += "&FORM_CD=" + pFORM_CD;
        url += "&FORM_VER=" + pFORM_VER;
        dts_parameter.SyncLoad = "true";
        const sbmOptions = {
            id : "sbm_dts_parameter",
            action : "/NewDisclosureStatistics.do",
            ref : "",
            target : "dts_parameter=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_parameter.SyncLoad = "false";
        await scwin.search1();
    }
};

/**
 * @method
