///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name sleep
 * @description sleep 처리
 * @param {*} numberMillis numberMillis
 * @returns {void}
 * @hidden N
 */
scwin.sleep = function(numberMillis) {
    let now = new Date();
    const exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};

/**
 * @method
 * @name OnSized
 * @description On Sized 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSized = function(winID) {

    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};

/**
 * @method
 * @name OnSizedMax
 * @description On Sized Max 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSizedMax = function(winID) {

    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    scwin.GauceObjResize($c.frame.path("/").width, frame.height);
};

/**
 * @method
 * @name OnWinStat
 * @description On Win Stat 처리
 * @param {String} winID winID
 * @param {*} statmsg statmsg
 * @returns {void}
 * @hidden N
 */
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg === "activate" && winID.substring(0, 6) === "Child_") {

        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg === "maximize") {
        scwin.maxval = 1;
    } else if (statmsg === "size") {
        if (scwin.maxval === 0) {
            const strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {

                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }

            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval === 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};

/**
 * @method
 * @name GauceObjResize
 * @description 그리드메인
 * @param {*} a a
 * @param {*} b b
 * @returns {void}
 * @hidden N
 */
scwin.GauceObjResize = function(a, b) {
    // 그리드메인
    const gw = (a - parseInt(grd_main1.getStyle("width")) - 30);
    grd_main1.ReDraw = "false";
    grd_main2.ReDraw = "false";
    grd_main1.setGridWidth(parseInt(grd_main1.getStyle("width")) + gw);
    grd_main2.setGridWidth(parseInt(grd_main2.getStyle("width")) + gw);
    grd_main1.ReDraw = "true";
    grd_main2.ReDraw = "true";
    scwin.gOldWidthSize = frame.width;

    // 탭패널
    panel_1.style.width = parseInt(panel_1.style.width.replace("px", "")) + gw;
    panel_2.style.width = parseInt(panel_2.style.width.replace("px", "")) + gw;

    // 저장버튼
    btn_save1.style.left = parseInt(btn_save1.style.left.replace("px", "")) + gw;
    btn_save2.style.left = parseInt(btn_save2.style.left.replace("px", "")) + gw;
};

/**
 * @method
 * @name CopyToClipboard
 * @description grid resize 종료부
 * @param {*} StartRow StartRow
 * @param {*} startColid startColid
 * @param {*} EndRow EndRow
 * @param {*} EndColid EndColid
 * @param {*} grdObj grdObj
 * @returns {void}
 * @hidden N
 */
scwin.CopyToClipboard = function(StartRow, startColid, EndRow, EndColid, grdObj) {
    let strMatrix = "";
    const StarColIndex = grdObj.GetColumnIndex(startColid);
    const EndColIndex = grdObj.GetColumnIndex(EndColid);
    for (i = StartRow; i <= EndRow; i++) {
        for (j = StarColIndex; j <= EndColIndex; j++) {

            strMatrix += grdObj.VirtualString2(i, grdObj.GetColumnID(j), 1);
            if (j !== EndColIndex) strMatrix += "\t";
        }
        strMatrix += "\r\n";
    }
    if (strMatrix !== "") {

        window.clipboardData.setData("Text", strMatrix);
        alert("클립보드에 복사 되었습니다.");
    }
};

