/**
 * @method
 * @name setOrder1
 * @description set Order1 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.setOrder1 = function(row, colid) {
    if (colid === "NEXT") {
        let vMax = 0;
        let vFORM_VER = dts_acode1.getCellData(row, "FORM_VER");
        txb_max1.setValue(1);
        for (let i = 1; i <= dts_acode1.getRowCount(); i++) {
            if ((parseInt(dts_acode1.getCellData(i, "SORT_ORD"), 10) > vMax) && (dts_acode1.getCellData(i, "FORM_VER") === vFORM_VER)) {
                vMax = parseInt(dts_acode1.getCellData(i, "SORT_ORD"), 10);
            }
        }
        txb_max1.setValue(vMax + 1);
        dts_acode1.setCellData(row, "SORT_ORD", txb_max1.getValue());
    }
};

